1	// Shared helpers for the jsonpatch test suites (not a test file itself).
2	import assert from 'node:assert/strict';
3	import { spawnSync } from 'node:child_process';
4	import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
5	import { tmpdir } from 'node:os';
6	import { join, dirname } from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	import { PatchError } from '../jsonpatch.mjs';
9	
10	const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
11	export const CLI = join(ROOT, 'jsonpatch-cli.mjs');
12	
13	// Runs the CLI with the given arguments; `stdin` (string or Buffer) is piped in when given.
14	export function runCli(args, { stdin = '', cwd } = {}) {
15	  const res = spawnSync(process.execPath, [CLI, ...args], {
16	    cwd,
17	    input: stdin,
18	    encoding: 'utf8',
19	    maxBuffer: 64 * 1024 * 1024,
20	  });
21	  if (res.error && res.error.code !== 'EPIPE') throw res.error;
22	  return { code: res.status, stdout: res.stdout, stderr: res.stderr };
23	}
24	
25	// Asserts a failed CLI run: exactly one stderr line, nothing on stdout, the given exit code.
26	export function assertCliError(res, code, line) {
27	  assert.equal(res.stderr, `${line}\n`);
28	  assert.equal(res.stdout, '');
29	  assert.equal(res.code, code);
30	}
31	
32	// Asserts a successful CLI run printing `expected` as JSON.stringify(x, null, 2) + "\n".
33	export function assertCliOk(res, expectedText) {
34	  assert.equal(res.stderr, '');
35	  assert.equal(res.stdout, expectedText);
36	  assert.equal(res.code, 0);
37	}
38	
39	// Creates a fresh temp directory; returns { dir, file(name, content), cleanup }.
40	export function makeTmp() {
41	  const dir = mkdtempSync(join(tmpdir(), 'jsonpatch-test-'));
42	  const file = (name, content) => {
43	    const path = join(dir, name);
44	    writeFileSync(path, content);
45	    return path;
46	  };
47	  return { dir, file, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
48	}
49	
50	// Asserts that fn throws a PatchError with exactly this message and index.
51	export function assertPatchError(fn, message, index) {
52	  let caught;
53	  try {
54	    fn();
55	  } catch (err) {
56	    caught = err;
57	  }
58	  assert.ok(caught !== undefined, `expected PatchError "${message}", nothing was thrown`);
59	  assert.ok(caught instanceof PatchError, `expected PatchError, got ${caught?.name}: ${caught?.message}`);
60	  assert.ok(caught instanceof Error);
61	  assert.equal(caught.name, 'PatchError');
62	  assert.equal(caught.message, message);
63	  assert.equal(caught.index, index);
64	}
65	
66	// Nested arrays: depth 1 is [], depth n is n levels of brackets.
67	export function nestedArrayText(depth) {
68	  return '['.repeat(depth) + ']'.repeat(depth);
69	}
70	
71	// Returns true when x is -0.
72	export const isNegZero = (x) => Object.is(x, -0);
