2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import { open, stat } from 'node:fs/promises';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const CHUNK_SIZE = 65536;
10	
11	class InputError extends Error {
12	  constructor(reason, exitCode) {
13	    super(reason);
14	    this.exitCode = exitCode;
15	  }
16	}
17	
18	const isContainer = (v) => v !== null && typeof v === 'object';
19	
20	async function isDirectory(path) {
21	  try {
22	    return (await stat(path)).isDirectory();
23	  } catch {
24	    return false;
25	  }
26	}
27	
28	async function readPath(path) {
29	  let handle;
30	  try {
31	    handle = await open(path, 'r');
32	  } catch (err) {
33	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw new InputError('no such file', 1);
34	    if (await isDirectory(path)) throw new InputError('is a directory', 1);
35	    throw new InputError('cannot read', 1);
36	  }
37	  try {
38	    if ((await handle.stat()).isDirectory()) throw new InputError('is a directory', 1);
39	    const chunks = [];
40	    let total = 0;
41	    for (;;) {
42	      const buffer = Buffer.alloc(CHUNK_SIZE);
43	      const { bytesRead } = await handle.read(buffer, 0, CHUNK_SIZE, null);
44	      if (bytesRead === 0) break;
45	      total += bytesRead;
46	      if (total > MAX_BYTES) throw new InputError('too large', 1);
47	      chunks.push(buffer.subarray(0, bytesRead));
48	    }
49	    return Buffer.concat(chunks);
50	  } catch (err) {
51	    if (err instanceof InputError) throw err;
52	    if (err.code === 'EISDIR') throw new InputError('is a directory', 1);
53	    throw new InputError('cannot read', 1);
54	  } finally {
55	    await handle.close().catch(() => {});
56	  }
57	}
58	
59	function readStdin() {
60	  return new Promise((resolve, reject) => {
61	    const chunks = [];
62	    let total = 0;
63	    const input = process.stdin;
64	    input.on('data', (chunk) => {
65	      total += chunk.length;
66	      if (total > MAX_BYTES) {
67	        input.destroy();
68	        reject(new InputError('too large', 1));
69	      } else {
70	        chunks.push(chunk);
71	      }
72	    });
73	    input.on('end', () => resolve(Buffer.concat(chunks)));
74	    input.on('error', () => reject(new InputError('cannot read', 1)));
75	  });
76	}
77	
78	function exceedsDepth(value, max) {
79	  const stack = [[value, 0]];
80	  while (stack.length > 0) {
81	    const [current, depth] = stack.pop();
82	    if (!isContainer(current)) continue;
83	    if (depth + 1 > max) return true;
84	    for (const child of Object.values(current)) stack.push([child, depth + 1]);
85	  }
86	  return false;
87	}
88	
89	async function load(arg) {
90	  const bytes = arg === '-' ? await readStdin() : await readPath(arg);
91	  let text;
92	  try {
93	    // The default decoder drops one leading byte order mark.
94	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
95	  } catch {
96	    throw new InputError('invalid UTF-8', 3);
97	  }
98	  let value;
99	  try {
100	    value = JSON.parse(text);
101	  } catch {
102	    throw new InputError('invalid JSON', 3);
103	  }
104	  if (exceedsDepth(value, MAX_DEPTH)) throw new InputError('too deep', 3);
105	  return value;
106	}
107	
108	// Same output as JSON.stringify(value, null, 2), without recursion, for results too deep for it.
109	function stringifyDeep(value) {
110	  const out = [];
111	  const stack = [{ value, indent: '' }];
112	  while (stack.length > 0) {
113	    const item = stack.pop();
114	    if (typeof item === 'string') {
115	      out.push(item);
116	      continue;
117	    }
118	    const { value: current, indent } = item;
119	    if (!isContainer(current)) {
120	      out.push(JSON.stringify(current));
121	      continue;
122	    }
123	    const keys = Array.isArray(current) ? null : Object.keys(current);
124	    const [openMark, closeMark] = keys ? ['{', '}'] : ['[', ']'];
125	    const count = keys ? keys.length : current.length;
126	    if (count === 0) {
127	      out.push(openMark + closeMark);
128	      continue;
129	    }
130	    const inner = `${indent}  `;
131	    const parts = [openMark];
132	    for (let i = 0; i < count; i++) {
133	      const label = keys ? `${JSON.stringify(keys[i])}: ` : '';
134	      parts.push(`${i > 0 ? ',' : ''}\n${inner}${label}`);
135	      parts.push({ value: current[keys ? keys[i] : i], indent: inner });
136	    }
137	    parts.push(`\n${indent}${closeMark}`);
138	    for (let i = parts.length - 1; i >= 0; i--) stack.push(parts[i]);
139	  }
140	  return out.join('');
141	}
142	
143	function stringify(value) {
144	  try {
145	    return JSON.stringify(value, null, 2);
146	  } catch (err) {
147	    if (err instanceof RangeError) return stringifyDeep(value);
148	    throw err;
149	  }
150	}
151	
152	function fail(message, exitCode) {
153	  process.stderr.write(`${message}\n`);
154	  process.exitCode = exitCode;
155	}
156	
157	async function main(args) {
158	  if (args.length < 1 || args.length > 2) return fail(USAGE, 2);
159	  const [patchArg, docArg = '-'] = args;
160	  if (patchArg === '-' && docArg === '-') return fail(USAGE, 2);
161	
162	  const inputs = [];
163	  for (const arg of [patchArg, docArg]) {
164	    try {
165	      inputs.push(await load(arg));
166	    } catch (err) {
167	      if (!(err instanceof InputError)) throw err;
168	      return fail(`Error: ${arg === '-' ? 'stdin' : arg}: ${err.message}`, err.exitCode);
169	    }
170	  }
171	
172	  const [patch, doc] = inputs;
173	  let result;
174	  try {
175	    result = applyPatch(doc, patch);
176	  } catch (err) {
177	    if (!(err instanceof PatchError)) throw err;
178	    return fail(`Error: ${err.message}`, 4);
179	  }
180	  process.stdout.write(`${stringify(result)}\n`);
181	  process.exitCode = 0;
182	}
183	
184	await main(process.argv.slice(2));
