  test('mode 000 file', { skip: isRoot && 'running as root' }, () => {
    const p = tmp.file('locked.json', '[]');
    fs.chmodSync(p, 0o000);
    try {
      assertCliError(run(['locked.json', okDoc()]), 1, 'Error: locked.json: cannot read');
    } finally {
